export function townChat(n,show,close){const life=n.ambient||'Живём от караула до караула. Пока стены держатся, держимся и мы.';const choices=()=>[['Как тебе живётся здесь?',()=>show(n.name,life,[['А что слышно на дорогах?',()=>show(n.name,'Обозов стало меньше. Одни винят зверей, другие — людей, которые обещают провести без дозора. Я бы шёл с теми, кого знаю в лицо.',choices())],['Спасибо за разговор',close]])],['Что знаешь об Ордене?',()=>show(n.name,'Они бьются с тем, против чего обычной стражи мало. За это им многое прощают. А что происходит за их стенами, горожане только гадают.',choices())],['Где найти припасы?',()=>show(n.name,'На западной улице работает Грета. К югу от западного рынка — алхимик Фабиан. Эльза торгует травами на востоке, Лина кормит у «Тёплого очага», а Торвальд шьёт сумки у северной стены. На карте отмечены все лавки.',choices())],['До встречи',close]];show(n.name,life,choices())}
